+	v2Store := checkpoint.NewV2GitStore(repo, v2URL)
+	preferV2 := settings.IsCheckpointsV2Enabled(ctx)
+
+	rows := make([]reviewBriefRow, 0, len(commits))
+	for _, commit := range commits {
+		row := reviewBriefRow{
