   790	// detectReviewScope runs a handful of cheap `git` queries to describe the
   791	// set of changes the user is about to review. Best-effort: any individual
   792	// query that fails leaves the corresponding field at its zero value.
   793	func detectReviewScope(ctx context.Context) (reviewScope, error) {
   794		repoRoot, err := paths.WorktreeRoot(ctx)
   795		if err != nil {
   796			return reviewScope{}, fmt.Errorf("locate repo root: %w", err)
   797		}
   798		var s reviewScope
   799		s.Branch = gitString(ctx, repoRoot, "rev-parse", "--abbrev-ref", "HEAD")
   800		if s.Branch == detachedHEADDisplay {
   801			s.Branch = ""
   802		}
   803		s.HeadSHA = gitString(ctx, repoRoot, "rev-parse", "--short", "HEAD")
   804		base := detectBaseBranchRef(ctx, repoRoot)
   805		s.Base = base.display
   806		s.BaseRef = base.ref
   807		headRef := s.Branch
