   834	func detectBaseBranchRef(ctx context.Context, repoRoot string) baseBranchRef {
   835		if target := gitString(ctx, repoRoot, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); target != "" {
   836			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", target) {
   837				return baseBranchRef{display: strings.TrimPrefix(target, "origin/"), ref: target}
   838			}
   839		}
   840		candidates := []string{defaultBaseBranch, masterBaseBranch}
   841		for _, candidate := range candidates {
   842			ref := "origin/" + candidate
   843			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/remotes/"+ref) {
   844				return baseBranchRef{display: candidate, ref: ref}
   845			}
   846		}
   847		for _, candidate := range candidates {
   848			if gitOK(ctx, repoRoot, "rev-parse", "--verify", "--quiet", "refs/heads/"+candidate) {
   849				return baseBranchRef{display: candidate, ref: candidate}
   850			}
   851		}
   852		return baseBranchRef{}
   853	}
